<script setup>
import { useForm, Link } from '@inertiajs/vue3'
import { ref } from 'vue'
const props = defineProps({ course:Object, role:String })
const create = useForm({ title:'', description:'' })
const editing = ref(null)
const edit = useForm({ title:'', description:'' })
const add = () => create.post(`/${props.role}/courses/${props.course.id}/sections`, { onSuccess:()=>create.reset() })
const beginEdit = section => { editing.value=section.id; edit.title=section.title; edit.description=section.description||'' }
const saveEdit = section => edit.put(`/${props.role}/courses/${props.course.id}/sections/${section.id}`, { onSuccess:()=>editing.value=null })
</script>
<template><section class="rounded-2xl border bg-white p-5"><div class="mb-4 flex flex-wrap justify-between gap-2"><h2 class="text-lg font-bold">ساختار دوره</h2><Link :href="`/${role}/courses/${course.id}/lessons/create`" class="rounded-xl bg-teal-700 px-4 py-2 text-white">درس جدید</Link></div>
<form class="mb-5 grid gap-2 sm:grid-cols-[1fr_auto]" @submit.prevent="add"><div><label for="new-section-title">عنوان فصل <span class="text-red-700">(الزامی)</span></label><input id="new-section-title" v-model="create.title" required><p class="mt-1 text-sm text-red-600">{{create.errors.title}}</p></div><button :disabled="create.processing" class="self-end rounded-xl border px-4 py-2 disabled:opacity-50">{{create.processing?'در حال افزودن…':'افزودن فصل'}}</button></form>
<div class="mb-5 space-y-2"><div v-for="section in course.sections" :key="section.id" class="rounded-xl bg-slate-50 p-3"><form v-if="editing===section.id" class="grid gap-2 sm:grid-cols-[1fr_auto_auto]" @submit.prevent="saveEdit(section)"><div><label :for="`section-${section.id}`">عنوان جدید فصل</label><input :id="`section-${section.id}`" v-model="edit.title" required autofocus><p class="text-sm text-red-600">{{edit.errors.title}}</p></div><button :disabled="edit.processing" class="self-end rounded-xl bg-teal-700 px-4 py-2 text-white">ذخیره</button><button type="button" class="self-end rounded-xl border px-4 py-2" @click="editing=null">انصراف</button></form><div v-else class="flex flex-wrap items-center justify-between gap-3"><div><strong>{{section.title}}</strong><span v-if="section.deleted_at" class="mr-2 text-xs text-red-700">بایگانی‌شده</span></div><div class="flex gap-3"><template v-if="!section.deleted_at"><button type="button" class="text-teal-700" @click="beginEdit(section)">ویرایش</button><Link :href="`/${role}/courses/${course.id}/sections/${section.id}/move/up`" method="post" as="button" aria-label="انتقال فصل به بالا">↑</Link><Link :href="`/${role}/courses/${course.id}/sections/${section.id}/move/down`" method="post" as="button" aria-label="انتقال فصل به پایین">↓</Link><Link :href="`/${role}/courses/${course.id}/sections/${section.id}`" method="delete" as="button" class="text-red-700">بایگانی</Link></template><Link v-else-if="role==='admin'" :href="`/admin/courses/${course.id}/sections/${section.id}/restore`" method="post" as="button" class="text-teal-700">بازیابی</Link></div></div></div></div>
<div class="space-y-2"><div v-for="lesson in course.lessons" :key="lesson.id" class="flex flex-wrap items-center justify-between rounded-xl border p-3" :class="lesson.deleted_at?'opacity-60':''"><div><strong>{{lesson.sort_order}}. {{lesson.title}}</strong><p class="text-xs text-slate-500">{{lesson.section?.title||'بدون فصل'}} — {{lesson.status}}</p></div><div v-if="!lesson.deleted_at" class="flex gap-2"><Link :href="`/${role}/courses/${course.id}/lessons/${lesson.id}/edit`" class="text-teal-700">ویرایش</Link><Link :href="`/${role}/courses/${course.id}/lessons/${lesson.id}/move/up`" method="post" as="button" aria-label="انتقال درس به بالا">↑</Link><Link :href="`/${role}/courses/${course.id}/lessons/${lesson.id}/move/down`" method="post" as="button" aria-label="انتقال درس به پایین">↓</Link><Link :href="`/${role}/courses/${course.id}/lessons/${lesson.id}`" method="delete" as="button" class="text-red-700">بایگانی</Link></div></div><p v-if="!course.lessons.length" class="rounded-xl border border-dashed p-5 text-center text-slate-500">هنوز درسی برای این دوره ساخته نشده است.</p></div></section></template>
